class GhostConv(nn.Module):
    def __init__(self, c1, c2, k=1, s=1, p=None, g=1, act=True):
        super().__init__()
        c_ = c2 // 2
        self.cv1 = Conv(c1, c_, k, s, p, g, act=act)
        self.cv2 = Conv(c_, c_, 5, 1, p, c_, act=act)

    def forward(self, x):
        y = self.cv1(x)
        return torch.cat((y, self.cv2(y)), 1)

class GhostBottleneck(nn.Module):
    def __init__(self, c1, c2, k=3, s=1):
        super().__init__()
        c_ = c2 // 2
        self.conv = nn.Sequential(
            GhostConv(c1, c_, 1, 1),
            DWConv(c_, c_, k, s, act=False),
            GhostConv(c_, c2, 1, 1, act=False),
        )
        self.shortcut = (
            nn.Sequential(DWConv(c1, c1, k, s, act=False), Conv(c1, c2, 1, 1, act=False)) if s == 2 else nn.Identity()
        )

    def forward(self, x):
        return self.conv(x) + self.shortcut(x)

class C3Ghost(C3):
    def __init__(self, c1, c2, n=1, shortcut=True, g=1, e=0.5):
        super().__init__(c1, c2, n, shortcut, g, e)
        c_ = int(c2 * e)
        self.m = nn.Sequential(*(GhostBottleneck(c_, c_) for _ in range(n)))

class SEBlock(nn.Module):
    def __init__(self, c1=None, reduction=16):
        super(SEBlock, self).__init__()
        self.c1 = c1
        self.reduction = reduction
        self.avg_pool = nn.AdaptiveAvgPool2d(1)
        if c1 is not None:
            self._build_fc_layers(c1)
        else:
            self.fc = None

    def _build_fc_layers(self, c1):
        self.fc = nn.Sequential(
            nn.Linear(c1, c1 // self.reduction, bias=False),
            nn.ReLU(inplace=True),
            nn.Linear(c1 // self.reduction, c1, bias=False),
            nn.Sigmoid()
        )

    def forward(self, x):
        b, c, _, _ = x.size()
        if self.fc is None:
            self.c1 = c
            self._build_fc_layers(c)
            if x.is_cuda:
                self.fc = self.fc.cuda()
        y = self.avg_pool(x).view(b, c)
        y = self.fc(y).view(b, c, 1, 1)
        return x * y.expand_as(x)

class SEBottleneck(Bottleneck):
    def __init__(self, c1, c2, shortcut=True, g=1, e=0.5, reduction=16):
        super().__init__(c1, c2, shortcut, g, e)
        self.se = SEBlock(c2, reduction)

    def forward(self, x):
        x = super().forward(x)
        x = self.se(x)
        return x

class C3SE(C3):
    def __init__(self, c1, c2, n=1, shortcut=True, g=1, e=0.5, reduction=16):
        super().__init__(c1, c2, n, shortcut, g, e)
        c_ = int(c2 * e)
        self.m = nn.Sequential(*(SEBottleneck(c_, c_, shortcut, g, e=1.0, reduction=reduction) for _ in range(n)))

class Expert(nn.Module):
    def __init__(self, c1, c2, k=3, s=1, p=None, g=1, act=True, expert_type='conv'):
        super(Expert, self).__init__()
        self.expert_type = expert_type
        if expert_type == 'conv':
            self.expert = Conv(c1, c2, k, s, p, g, act)
        elif expert_type == 'bottleneck':
            self.expert = Bottleneck(c1, c2, shortcut=False, g=g, e=0.5)
        elif expert_type == 'ghost':
            self.expert = GhostBottleneck(c1, c2, k, s)
        else:
            self.expert = Conv(c1, c2, k, s, p, g, act)

    def forward(self, x):
        return self.expert(x)

class MoELayer(nn.Module):
    def __init__(self, c1, c2, num_experts=4, top_k=2, expert_type='conv', k=3, s=1, p=None, g=1, act=True):
        super(MoELayer, self).__init__()
        self.num_experts = num_experts
        self.top_k = top_k
        self.experts = nn.ModuleList([
            Expert(c1, c2, k, s, p, g, act, expert_type)
            for _ in range(num_experts)
        ])
        self.gate = SparseGating(c1, num_experts, top_k)
        self.register_buffer('load_balancing_loss', torch.tensor(0.0))

    def forward(self, x):
        batch_size, channels, height, width = x.size()
        gates, indices, load_loss = self.gate(x)
        self.load_balancing_loss = load_loss
        output = torch.zeros(batch_size, self.experts[0].expert.cv1.conv.out_channels if hasattr(self.experts[0].expert, 'cv1') else self.experts[0].expert.conv.out_channels, height, width, device=x.device, dtype=x.dtype)
        for i in range(self.top_k):
            expert_indices = indices[:, i]
            expert_weights = gates[:, i:i+1]
            for expert_idx in range(self.num_experts):
                mask = (expert_indices == expert_idx)
                if mask.sum() == 0:
                    continue
                expert_input = x[mask]
                expert_weight = expert_weights[mask]
                if expert_input.size(0) > 0:
                    expert_output = self.experts[expert_idx](expert_input)
                    weighted_output = expert_output * expert_weight.view(-1, 1, 1, 1)
                    output[mask] += weighted_output
        return output

class C3MoE(C3):
    def __init__(self, c1, c2, n=1, shortcut=True, g=1, e=0.5, num_experts=4, top_k=2):
        super().__init__(c1, c2, n, shortcut, g, e)
        c_ = int(c2 * e)
        self.m = nn.Sequential(*(MoEBottleneck(c_, c_, shortcut, g, e=1.0, num_experts=num_experts, top_k=top_k) for _ in range(n)))

    def get_load_balancing_loss(self):
        total_loss = 0.0
        count = 0
        for module in self.m:
            if hasattr(module, 'cv2') and hasattr(module.cv2, 'load_balancing_loss'):
                loss_val = module.cv2.load_balancing_loss
                if isinstance(loss_val, torch.Tensor):
                    total_loss += loss_val.item()
                else:
                    total_loss += float(loss_val)
                count += 1
        return total_loss / max(count, 1)

class WeightedFeatureFusion(nn.Module):
    def __init__(self, num_inputs, eps=1e-4):
        super(WeightedFeatureFusion, self).__init__()
        self.num_inputs = num_inputs
        self.eps = eps
        self.weights = nn.Parameter(torch.ones(num_inputs, dtype=torch.float32), requires_grad=True)

    def forward(self, x):
        w = torch.clamp(self.weights, min=0.0)
        w = w / (torch.sum(w, dim=0) + self.eps)
        out = 0
        for i in range(self.num_inputs):
            out += x[i] * w[i]
        return out

class FocalLoss(nn.Module):
    def __init__(self, loss_fcn, gamma=1.5, alpha=0.25):
        super().__init__()
        self.loss_fcn = loss_fcn
        self.gamma = gamma
        self.alpha = alpha
        self.reduction = loss_fcn.reduction
        self.loss_fcn.reduction = 'none'

    def forward(self, pred, true):
        loss = self.loss_fcn(pred, true)
        pred_prob = torch.sigmoid(pred)
        p_t = true * pred_prob + (1 - true) * (1 - pred_prob)
        alpha_factor = true * self.alpha + (1 - true) * (1 - self.alpha)
        modulating_factor = (1.0 - p_t) ** self.gamma
        loss *= alpha_factor * modulating_factor
        if self.reduction == 'mean':
            return loss.mean()
        elif self.reduction == 'sum':
            return loss.sum()
        else:
            return loss
